def _calculate_total(o):
    t = 0
    for i in o["items"]:
        t += i["price"] * i["qty"]
    if t > 100:
        t *= 0.9
    if o.get("member"):
        t *= 0.95
    return t


def calc(o):
    """Return the calculated total for an order."""
    try:
        return round(_calculate_total(o), 2)
    except (TypeError, KeyError):
        return 0


def calc2(o):
    """Return the calculated total for an invoice, including shipping."""
    try:
        t = _calculate_total(o)
        t += o.get("shipping", 0)
        return round(t, 2)
    except (TypeError, KeyError):
        return 0

